declare(strict_types=1);
use BYPCMS\Core\{Business,Content};
require_once __DIR__.'/Business.php';
$business=new Business($db,$config,BYPCMS_ROOT);$e=[Content::class,'e'];$admin=in_array($user['role'],['owner','admin'],true);$error=$error??'';$notice=$notice??'';
if(!in_array($user['role'],['owner','admin','editor','manager'],true)){http_response_code(403);exit('Доступ запрещён.');}
if(in_array($section,['mail','staff','forms'],true)&&!$admin){http_response_code(403);exit('Настройки доступны администратору.');}
$states=Business::STATES;$mailLabels=['pending'=>'Ожидает отправки','sending'=>'Передаётся SMTP','accepted'=>'Принято SMTP','failed'=>'Ошибка отправки','uncertain'=>'Результат неизвестен'];
if($_SERVER['REQUEST_METHOD']==='POST')try {
    if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Сессия истекла. Обновите страницу.');
    $action=$_POST['action']??'';
    if($action==='lead_save'){$business->updateLead($_POST,$user);$_SESSION['content_notice']='Заявка обновлена.';header('Location: /manage/?section=leads&lead='.(int)$_POST['id']);return;}
    if($action==='bulk_leads'){
        $ids=array_values(array_unique(array_map('intval',(array)($_POST['ids']??[]))));if(!$ids||count($ids)>100||!isset($states[$_POST['bulk_status']??'']))throw new RuntimeException('Выберите записи и действие.');$fail=[];$ok=0;$failed=[];
        foreach($ids as $id)try{$v=$business->lead($id,$user);if($v['status']!==$_POST['bulk_status'])$business->updateLead(array_merge($v,['status'=>$_POST['bulk_status'],'assignee_id'=>$user['role']==='manager'?$user['id']:$v['assignee_id']]),$user);$ok++;}catch(Throwable $x){$fail[]='#'.$id.': '.$x->getMessage();$failed[]=$id;}
        $notice='Обновлено: '.$ok.'.';$error=implode(' ',$fail);$_POST['ids']=$failed;
        if(!$fail){$_SESSION['content_notice']=$notice;header('Location: /manage/?'.http_build_query(['section'=>'leads','q'=>$_GET['q']??'','status'=>$_GET['status']??'','page'=>$_GET['page']??1]));return;}
    }
    if($action==='mail_configure'){if(!$admin)throw new RuntimeException('Нет прав.');$business->configureMail($_POST);$notice='Параметры SMTP сохранены. Секрет не отображается в интерфейсе.';}
    if($action==='mail_send'){if(!$admin)throw new RuntimeException('Нет прав.');$business->sendMail((int)$_POST['lead_id'],!empty($_POST['acknowledge']));$notice='SMTP подтвердил приём уведомления. Это не подтверждение прочтения получателем.';}
    if($action==='forms_toggle'){
        if(!$admin)throw new RuntimeException('Нет прав.');
        if(!$db->one('SELECT id FROM byp_modules WHERE module_key="forms"'))throw new RuntimeException('Модуль форм не входит в эту установку.');
        $db->execute('UPDATE byp_modules SET status=?,updated_at=NOW() WHERE module_key="forms"',[!empty($_POST['forms_enabled'])?'active':'inactive']);
        $notice='Настройка формы сохранена. Ранее полученные заявки остаются в CRM.';
    }
    if($action==='staff_save'){
        if(!$admin)throw new RuntimeException('Нет прав.');$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$role=$_POST['role']??'';$password=$_POST['password']??'';$id=(int)($_POST['id']??0);
        if(!$name||mb_strlen($name)>150||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190||!in_array($role,['editor','manager'],true)||(($password!==''||!$id)&&strlen($password)<12))throw new RuntimeException('Укажите имя, email, роль и пароль от 12 символов для нового сотрудника.');
        if($id){$old=$db->one('SELECT u.*,r.slug role FROM byp_users u JOIN byp_roles r ON r.id=u.role_id WHERE u.id=?',[$id]);if(!$old||!in_array($old['role'],['editor','manager'],true)||(int)$user['id']===$id)throw new RuntimeException('Эта учётная запись недоступна для изменения.');}
        $pdo=$db->pdo();$pdo->beginTransaction();try {
            $db->execute('INSERT IGNORE INTO byp_roles(slug,name,permissions,created_at,updated_at) VALUES(?,?,"[]",NOW(),NOW())',[$role,$role==='editor'?'Редактор':'Менеджер']);$rid=$db->one('SELECT id FROM byp_roles WHERE slug=?',[$role])['id'];$status=($_POST['status']??'active')==='blocked'?'blocked':'active';
            if($id){$db->execute('UPDATE byp_users SET role_id=?,name=?,email=?,status=?,updated_at=NOW() WHERE id=?',[$rid,$name,$email,$status,$id]);if($password!=='')$db->execute('UPDATE byp_users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$id]);}
            else $id=$db->insert('INSERT INTO byp_users(role_id,name,email,password_hash,status,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())',[$rid,$name,$email,password_hash($password,PASSWORD_DEFAULT),$status]);
            $db->execute('INSERT INTO byp_audit_logs(user_id,action,entity_type,entity_id,created_at) VALUES(?,"business.staff.save","user",?,NOW())',[$user['id'],$id]);$pdo->commit();
        }catch(Throwable $x){$pdo->rollBack();throw $x;}
        $_SESSION['content_notice']='Сотрудник сохранён.';header('Location: /manage/?section=staff');return;
    }
}catch(Throwable $x){$error=$x instanceof PDOException?'Не удалось сохранить. Возможно, email уже используется.':$x->getMessage();}
$notice=$notice?:($_SESSION['content_notice']??'');unset($_SESSION['content_notice']);$settings=$business->settings();$staff=$db->all('SELECT u.id,u.name,u.email,u.status,r.slug role FROM byp_users u JOIN byp_roles r ON r.id=u.role_id WHERE r.slug IN ("owner","admin","editor","manager") ORDER BY u.id');
