?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= $e($_SESSION['csrf']) ?>"><title>Business · <?= $e($settings['site_name']) ?></title><link rel="stylesheet" href="<?= $e(Content::asset('/themes/journal/admin.css')) ?>?v=2.2.0"><script src="<?= $e(Content::asset('/themes/journal/admin.js')) ?>?v=2.2.0" defer></script></head><body><aside class="c-sidebar"><a class="c-brand" href="/manage/">B <span>BYPCMS / Business</span></a><p class="c-site-name"><?= $e($settings['site_name']) ?></p><nav aria-label="Разделы панели"><?php foreach($sectionLabels as $key=>$label): if(!$admin&&in_array($key,['mail','staff','forms'],true))continue;if($user['role']==='manager'&&$key!=='leads')continue; ?><a <?= $section===$key?'aria-current="page"':'' ?> href="/manage/?section=<?= $key ?>"><?= $label ?></a><?php endforeach ?><hr><a href="/admin/?section=license">Лицензия</a><a href="/admin/?section=updates">Обновления</a></nav><form method="post"><?php $hidden(); ?><button name="action" value="logout">Выйти</button></form></aside><div class="c-workspace"><header class="c-top"><span>Редакция Business</span><a href="/" target="_blank" rel="noopener">Открыть сайт ↗</a></header><main class="c-main">
