<?php if($section==='leads'&&!empty($_GET['lead'])): try{$lead=$business->lead((int)$_GET['lead'],$user);}catch(Throwable $x){http_response_code(404);echo '<h1>Заявка недоступна</h1></main></div></body></html>';return;}$context=json_decode($lead['context_json'],true);$v=$error?array_merge($lead,$_POST):$lead;$mail=$db->one('SELECT * FROM byp_business_mail WHERE lead_id=?',[$lead['id']]); ?>
<a href="/manage/?section=leads">← Все заявки</a><h1>Заявка <?= $e($lead['reference']) ?></h1><div class="c-editor-grid"><section class="c-card"><h2><?= $e($lead['name']) ?></h2><p><?= $e($lead['email']) ?> · <?= $e($lead['phone']) ?></p><p style="white-space:pre-wrap"><?= $e($lead['message']) ?></p><hr><?php foreach($context as $c): $currentContext=$content->get((int)$c['id']);$contextHref=$currentContext?(Business::published($currentContext)?'/'.$currentContext['slug'].'/':'/manage/?section='.($currentContext['kind']==='service'?'services':'projects').'&editor='.$currentContext['id']):null; ?><p>Контекст: <a href="<?= $e($contextHref??('/'.$c['slug'].'/')) ?>" target="_blank" rel="noopener"><?= $e($c['title']) ?></a></p><?php endforeach ?><p>Согласие: <?= $e($lead['consent_at']) ?> · <?= $e($lead['consent_version']) ?></p><p>Создана: <?= $e($lead['created_at']) ?></p><h3>Уведомление</h3><p><?= $e(['pending'=>'Ожидает отправки','sending'=>'Передаётся SMTP','accepted'=>'Принято SMTP','failed'=>'Ошибка отправки','uncertain'=>'Результат неизвестен'][$mail['state']]??$mail['state']) ?> · попыток: <?= (int)$mail['attempts'] ?></p><?php if($mail['last_error']): ?><p class="c-error"><?= $e($mail['last_error']) ?></p><?php endif ?><p>Заявка сохранена независимо от доставки письма.</p><?php if($admin): ?><a href="/manage/?section=mail">Настройки и очередь уведомлений →</a><?php endif ?></section><form class="c-card" method="post"><?php $hidden(); ?><input type="hidden" name="id" value="<?= $lead['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$v['revision'] ?>"><label>Статус<select name="status"><?php foreach($states as $key=>$label): ?><option value="<?= $key ?>" <?= $v['status']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label>Ответственный<select name="assignee_id"><option value="">Не назначен</option><?php foreach($staff as $person)if($person['status']==='active'): ?><option value="<?= $person['id'] ?>" <?= (int)$v['assignee_id']===$person['id']?'selected':'' ?>><?= $e($person['name']) ?></option><?php endif ?></select></label><label>Заметки<textarea name="notes" rows="8" maxlength="10000"><?= $e($v['notes']) ?></textarea></label><button class="c-primary" name="action" value="lead_save">Сохранить заявку</button></form></div>
<?php elseif($section==='leads'):
 $where=[];$params=[];$q=mb_substr(trim($_GET['q']??''),0,100);$filter=$_GET['status']??'';if($user['role']==='manager'){$where[]='(l.assignee_id IS NULL OR l.assignee_id=?)';$params[]=$user['id'];}if($q!==''){$where[]='(l.name LIKE ? OR l.email LIKE ? OR l.reference LIKE ?)';array_push($params,'%'.$q.'%','%'.$q.'%','%'.$q.'%');}if(isset($states[$filter])){$where[]='l.status=?';$params[]=$filter;}$sql=$where?' WHERE '.implode(' AND ',$where):'';$total=(int)$db->one('SELECT COUNT(*) n FROM byp_business_leads l'.$sql,$params)['n'];$pages=max(1,(int)ceil($total/20));$page=min($pages,max(1,(int)($_GET['page']??1)));$rows=$db->all('SELECT l.*,u.name assignee_name,m.state mail_state FROM byp_business_leads l LEFT JOIN byp_users u ON u.id=l.assignee_id LEFT JOIN byp_business_mail m ON m.lead_id=l.id'.$sql.' ORDER BY l.id DESC LIMIT 20 OFFSET '.(($page-1)*20),$params); ?>
<h1>Заявки / CRM</h1><p>Обращения с сайта. Письмо — отдельное уведомление; данные заявки уже сохранены.</p><form class="c-filters" method="get"><input type="hidden" name="section" value="leads"><input name="q" aria-label="Поиск заявок" placeholder="Имя, email или номер" value="<?= $e($q) ?>"><select name="status" aria-label="Фильтр статуса"><option value="">Все статусы</option><?php foreach($states as $key=>$label): ?><option value="<?= $key ?>" <?= $filter===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><button>Найти</button></form>
<form method="post" id="bulk-form"><?php $hidden(); ?><input type="hidden" name="action" value="bulk_leads"><div class="c-actions c-bulk"><span id="selection-count">Выбрано: 0</span><select name="bulk_status" aria-label="Действие с выбранными"><option value="">Выберите статус</option><?php foreach($states as $key=>$label): ?><option value="<?= $key ?>"><?= $label ?></option><?php endforeach ?></select><button id="bulk-submit" disabled>Применить</button></div><div class="c-table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="Выбрать все строки на странице"></th><th>Обращение</th><th>Статус</th><th>Ответственный</th><th>Письмо</th><th>Действия</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><input type="checkbox" name="ids[]" value="<?= $r['id'] ?>" aria-label="Выбрать <?= $e($r['reference']) ?>" <?= in_array($r['id'],$_POST['ids']??[])?'checked':'' ?>></td><td><?= $e($r['name']) ?><br><small><?= $e($r['reference'].' · '.$r['created_at']) ?></small></td><td><?= $e($states[$r['status']]??$r['status']) ?></td><td><?= $e($r['assignee_name']??'Не назначен') ?></td><td><?= $e($mailLabels[$r['mail_state']]??$r['mail_state']) ?></td><td><a href="/manage/?section=leads&lead=<?= $r['id'] ?>">Открыть →</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6">Заявок по этим условиям пока нет.</td></tr><?php endif ?></tbody></table></div></form><nav class="c-pagination" aria-label="Страницы заявок"><?php for($n=1;$n<=$pages;$n++): ?><a <?= $page===$n?'aria-current="page"':'' ?> href="/manage/?<?= $e(http_build_query(['section'=>'leads','q'=>$q,'status'=>$filter,'page'=>$n])) ?>"><?= $n ?></a><?php endfor ?></nav>
