<h1>Почта и уведомления</h1><p>Настройки SMTP для уведомлений о заявках. Данные заявок остаются в CRM при любой ошибке почты. Для автоматической отправки настройте cron по инструкции выпуска.</p><div class="c-editor-grid"><form class="c-card" method="post"><?php $hidden(); ?><input type="hidden" name="action" value="mail_configure"><label class="c-check"><input type="checkbox" name="smtp_enabled" value="1" <?= $mailSettings['smtp_enabled']?'checked':'' ?>> Включить SMTP</label><?php foreach(['smtp_host'=>'Сервер SMTP','smtp_user'=>'Логин SMTP','from_email'=>'Email отправителя','from_name'=>'Имя отправителя','owner_email'=>'Получатель заявок']as $key=>$label): ?><label><?= $label ?><input name="<?= $key ?>" value="<?= $e($_POST[$key]??$mailSettings[$key]) ?>" <?= str_ends_with($key,'email')?'type="email"':'' ?>></label><?php endforeach ?><label>Защита<select name="smtp_security"><option value="starttls">STARTTLS · 587</option><option value="ssl" <?= $mailSettings['smtp_security']==='ssl'?'selected':'' ?>>SSL · 465</option></select></label><label>Порт<select name="smtp_port"><option value="587">587</option><option value="465" <?= $mailSettings['smtp_port']===465?'selected':'' ?>>465</option></select></label><label>Пароль SMTP <?= $mailSettings['smtp_password_saved']?'(сохранён)':'' ?><input type="password" name="smtp_password" autocomplete="new-password" placeholder="Пусто — сохранить прежний"></label><label class="c-check"><input type="checkbox" name="clear_password" value="1"> Удалить сохранённый пароль</label><button class="c-primary">Сохранить SMTP</button></form><section class="c-card"><h2>Очередь уведомлений</h2><?php $mailPage=max(1,(int)($_GET['page']??1));$queue=$db->all('SELECT m.*,l.reference FROM byp_business_mail m JOIN byp_business_leads l ON l.id=m.lead_id ORDER BY m.id DESC LIMIT 20 OFFSET '.(($mailPage-1)*20));foreach($queue as $m): ?><form method="post" data-confirm="Отправить уведомление по этой заявке? Другую заявку это не создаёт."><?php $hidden(); ?><input type="hidden" name="lead_id" value="<?= $m['lead_id'] ?>"><h3><a href="/manage/?section=leads&lead=<?= $m['lead_id'] ?>"><?= $e($m['reference']) ?></a></h3><p><?= $e($mailLabels[$m['state']]??$m['state']) ?> · попыток <?= $m['attempts'] ?></p><?php if($m['last_error']): ?><p class="c-error"><?= $e($m['last_error']) ?></p><?php endif; if(!in_array($m['state'],['accepted','sending'],true)||($m['state']==='sending'&&strtotime($m['lease_until'])<time())): ?><label class="c-check"><input type="checkbox" name="acknowledge" value="1"> Проверил получателя: разрешаю повтор при неизвестном результате</label><button name="action" value="mail_send">Отправить / повторить</button><?php endif ?><hr></form><?php endforeach; if(!$queue): ?><p>Очередь пуста.</p><?php endif ?><nav><?php if($mailPage>1): ?><a href="/manage/?section=mail&page=<?= $mailPage-1 ?>">← Предыдущие</a><?php endif; if(count($queue)===20): ?><a href="/manage/?section=mail&page=<?= $mailPage+1 ?>">Следующие →</a><?php endif ?></nav></section></div>
